    function Square(x : Int) : Int {
        return x * x;
    }
}

function Double(x : Int) : Int {
    // pure, classical -- a function
    return x * 2;
}

operation PrepareAndMeasure() : Result {
    // touches a qubit -- must be an operation
    use q = Qubit();
    H(q);
    return M(q);
}

