operation Greet(name : String) : Unit {
    Message($"Hello, {name}!");
}

operation FlipUntilOne() : Int {
    mutable attempts = 0;
    mutable outcome = Zero;
    use q = Qubit();
    repeat {
        H(q);
        set attempts += 1;
        set outcome = M(q);
        Reset(q);
    } until outcome == One;
    return attempts;
}
